import {
  validatePremiumCollection,
  type PremiumCollectionConfig,
  type PremiumDepth,
  type PremiumPromptItem,
} from "@/data/premiumTypes";

type EthicsSeed = [
  prompt: string,
  category: string,
  audience: string,
  useCase: string,
  duration: string,
  depth: PremiumDepth,
  choiceA: string,
  choiceB: string,
  values: string[],
  followUps: string[],
];

function buildEthics(prefix: string, seeds: EthicsSeed[], facilitationTip: string): PremiumPromptItem[] {
  return seeds.map((seed, index) => ({
    id: `${prefix}-${String(index + 1).padStart(2, "0")}`,
    prompt: seed[0],
    category: seed[1],
    audience: seed[2],
    useCase: seed[3],
    duration: seed[4],
    depth: seed[5],
    choices: [seed[6], seed[7]],
    values: seed[8],
    followUps: seed[9],
    facilitationTip,
  }));
}

